    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

:root {
    --bg-primary: #0f172a;
    --bg-secondary: #1a2847;
    --bg-tertiary: #243056;
    --text-primary: #f1f5f9;
    --text-secondary: #cbd5e1;
    --accent: #3b82f6;
    --accent-hover: #2563eb;
    --border-color: #334155;
    --focus-color: #60a5fa;
}

@media (prefers-color-scheme: light) {
    :root {
        --bg-primary: #ffffff;
        --bg-secondary: #f8fafc;
        --bg-tertiary: #f1f5f9;
        --text-primary: #0f172a;
        --text-secondary: #475569;
        --accent: #2563eb;
        --accent-hover: #1d4ed8;
        --border-color: #e2e8f0;
        --focus-color: #3b82f6;
    }
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
    background-color: var(--bg-primary);
    color: var(--text-primary);
    line-height: 1.6;
}

/* Header */
header {
    background-color: var(--bg-secondary);
    border-bottom: 1px solid var(--border-color);
    padding: 3rem 2rem;
}

.header-content {
    max-width: 900px;
    margin: 0 auto;
}

header h1 {
    font-size: 2.5rem;
    font-weight: 700;
    margin-bottom: 0.5rem;
    color: var(--accent);
}

.subtitle {
    font-size: 1.1rem;
    color: var(--text-secondary);
}

/* Main content */
main {
    max-width: 900px;
    margin: 0 auto;
    padding: 3rem 2rem;
    min-height: 60vh;
}

.faq-container {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

/* Example section wrapper */
.example {
    background-color: var(--bg-secondary);
    border: 1px solid var(--border-color);
    border-radius: 0.75rem;
    overflow: hidden;
    transition: all 0.2s ease-in-out;
}

.example:hover {
    border-color: var(--accent);
    box-shadow: 0 4px 12px rgba(59, 130, 246, 0.1);
}

/* Details (disclosure widget) */
.details {
    all: unset;
    display: block;
    cursor: pointer;
}

.details summary {
    display: flex;
    align-items: center;
    padding: 1.5rem;
    cursor: pointer;
    user-select: none;
    font-size: 1.1rem;
    font-weight: 500;
    color: var(--text-primary);
    position: relative;
    transition: background-color 0.2s ease-in-out;
}

.details summary:hover {
    background-color: var(--bg-tertiary);
}

/* Focus indicator for accessibility */
.details summary:focus-visible {
    outline: 2px solid var(--focus-color);
    outline-offset: -2px;
    background-color: var(--bg-tertiary);
}

/* Summary arrow/chevron */
.details summary::before {
    content: '›';
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.5rem;
    height: 1.5rem;
    margin-right: 1rem;
    font-size: 1.5rem;
    color: var(--accent);
    transform: rotate(0deg);
    transition: transform 0.3s ease-in-out;
    flex-shrink: 0;
}

.details[open] summary::before {
    transform: rotate(90deg);
}

/* Answer content */
.details .answer {
    padding: 1.5rem;
    border-top: 1px solid var(--border-color);
    background-color: var(--bg-primary);
    animation: slideDown 0.3s ease-in-out;
}

.details .answer p {
    margin-bottom: 1rem;
    color: var(--text-secondary);
    line-height: 1.7;
}

.details .answer p:last-child {
    margin-bottom: 0;
}

/* Animation for answer reveal */
@keyframes slideDown {
    from {
        opacity: 0;
        transform: translateY(-10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* Respect reduced motion preferences */
@media (prefers-reduced-motion: reduce) {
    .example {
        transition: none;
    }

    .details summary {
        transition: none;
    }

    .details summary::before {
        transition: none;
    }

    .details .answer {
        animation: none;
    }
}

/* Footer */
footer {
    background-color: var(--bg-secondary);
    border-top: 1px solid var(--border-color);
    padding: 2rem;
    text-align: center;
    color: var(--text-secondary);
    font-size: 0.95rem;
}

/* Responsive design */
@media (max-width: 768px) {
    header {
        padding: 2rem 1.5rem;
    }

    header h1 {
        font-size: 1.8rem;
    }

    .subtitle {
        font-size: 1rem;
    }

    main {
        padding: 2rem 1.5rem;
    }

    .details summary {
        padding: 1.25rem;
        font-size: 1rem;
    }

    .details .answer {
        padding: 1.25rem;
    }
}

@media (max-width: 480px) {
    header {
        padding: 1.5rem 1rem;
    }

    header h1 {
        font-size: 1.5rem;
    }

    .subtitle {
        font-size: 0.95rem;
    }

    main {
        padding: 1.5rem 1rem;
    }

    .details summary {
        padding: 1rem;
        font-size: 0.95rem;
    }

    .details .answer {
        padding: 1rem;
    }

    .details summary::before {
        width: 1.25rem;
        height: 1.25rem;
        font-size: 1.25rem;
        margin-right: 0.75rem;
    }
}

/* Forced colors mode support */
@media (forced-colors: active) {
    .example {
        border: 1px solid CanvasText;
    }

    .details summary {
        color: CanvasText;
    }

    .details summary::before {
        color: CanvasText;
    }

    .details .answer {
        border-top-color: CanvasText;
        color: CanvasText;
    }

    header {
        border-bottom-color: CanvasText;
    }

    footer {
        border-top-color: CanvasText;
    }

    .example:hover {
        border-color: Highlight;
        background-color: Highlight;
        color: HighlightText;
    }

    .details summary:hover {
        background-color: Highlight;
        color: HighlightText;
    }

    .details summary:hover::before {
        color: HighlightText;
    }
}
