+.example {
+    background-color: var(--bg-secondary);
+    border: 1px solid var(--border-color);
+    border-radius: 0.75rem;
+    overflow: hidden;
+    transition: all 0.2s ease-in-out;
+}
+
+.example:hover {
+    border-color: var(--accent);
+    box-shadow: 0 4px 12px rgba(59, 130, 246, 0.1);
+}
+
+/* Details (disclosure widget) */
+.details {
+    all: unset;
+    display: block;
+    cursor: pointer;
+}
+
+.details summary {
+    display: flex;
+    align-items: center;
+    padding: 1.5rem;
+    cursor: pointer;
+    user-select: none;
+    font-size: 1.1rem;
+    font-weight: 500;
+    color: var(--text-primary);
+    position: relative;
+    transition: background-color 0.2s ease-in-out;
+}
+
+.details summary:hover {
+    background-color: var(--bg-tertiary);
+}
+
+/* Focus indicator for accessibility */
+.details summary:focus-visible {
+    outline: 2px solid var(--focus-color);
+    outline-offset: -2px;
+    background-color: var(--bg-tertiary);
+}
+
+/* Summary arrow/chevron */
+.details summary::before {
+    content: '›';
+    display: inline-flex;
+    align-items: center;
+    justify-content: center;
+    width: 1.5rem;
+    height: 1.5rem;
+    margin-right: 1rem;
+    font-size: 1.5rem;
+    color: var(--accent);
+    transform: rotate(0deg);
+    transition: transform 0.3s ease-in-out;
+    flex-shrink: 0;
+}
+
+.details[open] summary::before {
+    transform: rotate(90deg);
+}
+
+/* Answer content */
+.details .answer {
+    padding: 1.5rem;
+    border-top: 1px solid var(--border-color);
+    background-color: var(--bg-primary);
+    animation: slideDown 0.3s ease-in-out;
+}
+
+.details .answer p {
+    margin-bottom: 1rem;
+    color: var(--text-secondary);
+    line-height: 1.7;
+}
+
+.details .answer p:last-child {
+    margin-bottom: 0;
+}
+
+/* Animation for answer reveal */
+@keyframes slideDown {
+    from {
+        opacity: 0;
+        transform: translateY(-10px);
+    }
+    to {
+        opacity: 1;
+        transform: translateY(0);
+    }
+}
+
+/* Respect reduced motion preferences */
+@media (prefers-reduced-motion: reduce) {
+    .example {
+        transition: none;
+    }
+
+    .details summary {
+        transition: none;
+    }
+
+    .details summary::before {
+        transition: none;
+    }
+
+    .details .answer {
+        animation: none;
+    }
+}
+
+/* Footer */
+footer {
+    background-color: var(--bg-secondary);
+    border-top: 1px solid var(--border-color);
+    padding: 2rem;
+    text-align: center;
+    color: var(--text-secondary);
+    font-size: 0.95rem;
+}
+
+/* Responsive design */
+@media (max-width: 768px) {
+    header {
+        padding: 2rem 1.5rem;
+    }
+
+    header h1 {
+        font-size: 1.8rem;
+    }
+
+    .subtitle {
+        font-size: 1rem;
+    }
+
+    main {
+        padding: 2rem 1.5rem;
+    }
+
+    .details summary {
+        padding: 1.25rem;
+        font-size: 1rem;
+    }
+
+    .details .answer {
+        padding: 1.25rem;
+    }
+}
+
+@media (max-width: 480px) {
+    header {
+        padding: 1.5rem 1rem;
+    }
+
+    header h1 {
+        font-size: 1.5rem;
+    }
+
+    .subtitle {
+        font-size: 0.95rem;
+    }
+
+    main {
+        padding: 1.5rem 1rem;
+    }
+
+    .details summary {
+        padding: 1rem;
+        font-size: 0.95rem;
+    }
+
+    .details .answer {
+        padding: 1rem;
+    }
+
+    .details summary::before {
+        width: 1.25rem;
+        height: 1.25rem;
+        font-size: 1.25rem;
+        margin-right: 0.75rem;
+    }
+}
+
+/* Forced colors mode support */
