const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

(async () => {
    const htmlPath = path.join(__dirname, 'index.html');
    const axePath = path.join(__dirname, 'node_modules/axe-core/axe.min.js');

    const browser = await chromium.launch();
    const page = await browser.newPage();

    // Load HTML file
    const htmlContent = fs.readFileSync(htmlPath, 'utf8');
    await page.setContent(htmlContent, { waitUntil: 'load' });

    // Inject and run axe
    await page.addScriptTag({ path: axePath });
    const results = await page.evaluate(() => window.axe.run());

    await browser.close();

    // Separate WCAG violations from best-practice
    const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
    const bp = results.violations.filter(v => v.tags.includes('best-practice'));

    const output = {
        wcag: wcag.map(v => ({
            id: v.id,
            impact: v.impact,
            description: v.description,
            targets: v.nodes.map(n => n.target)
        })),
        bp: bp.map(v => ({
            id: v.id,
            description: v.description,
            targets: v.nodes.map(n => n.target)
        })),
        passes: results.passes.length,
        inapplicable: results.inapplicable.length
    };

    console.log(JSON.stringify(output, null, 2));
    process.exit(wcag.length > 0 ? 1 : 0);
})();

